const now = new Date().toISOString();
return [{ json: {
  execution: {
    id: `CONTROLLED-FAILURE-${Date.now()}`,
    mode: 'manual_canary',
    error: { message: 'Controlled validation failure for Langfuse observability verification' },
    lastNodeExecuted: 'Validate Workflow Input',
    url: null
  },
  workflow: {
    id: 'NXJLNsdf3N8HfrnQ',
    name: 'PRD Genie - Requirement Extractor + Langfuse v0.2'
  },
  canary: true,
  occurred_at: now
} }];

const source = $json;
const execution = source.execution || {};
const workflow = source.workflow || {};
const error = execution.error || source.error || {};
const randomHex = (length) => Array.from({ length }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const traceId = randomHex(32);
const spanId = randomHex(16);
const started = BigInt(Date.now()) * 1000000n;
const ended = started + 1000000n;
const failedNode = execution.lastNodeExecuted || error.node?.name || 'unknown';
const errorMessage = String(error.message || error.description || 'Unknown workflow failure').slice(0, 1000);
const runId = source.run_id || execution.id || `FAILURE-${Date.now()}`;
const testId = source.test_id || (source.canary ? 'FAILURE-CANARY' : 'UNSPECIFIED');
const attr = (key, value) => ({ key, value: { stringValue: typeof value === 'string' ? value : JSON.stringify(value) } });
const attributes = [
  attr('langfuse.trace.name', 'prd-genie-failure'),
  attr('langfuse.environment', 'evaluation'),
  attr('langfuse.version', 'failure-observer-v0.1.0'),
  attr('langfuse.trace.tags', ['capstone', 'failure-path', testId]),
  attr('langfuse.trace.metadata.run_id', runId),
  attr('langfuse.trace.metadata.test_id', testId),
  attr('langfuse.trace.metadata.source_workflow_id', workflow.id || 'unknown'),
  attr('langfuse.trace.metadata.source_workflow_name', workflow.name || 'unknown'),
  attr('langfuse.observation.type', 'span'),
  attr('langfuse.observation.input', { workflow_id: workflow.id || null, workflow_name: workflow.name || null, execution_id: execution.id || null, execution_mode: execution.mode || null }),
  attr('langfuse.observation.output', { outcome: 'failed', failed_node: failedNode, error_category: source.canary ? 'controlled_validation_failure' : 'workflow_execution_failure' }),
  attr('langfuse.observation.metadata.failed_node', failedNode),
  attr('langfuse.observation.metadata.error_message', errorMessage),
  attr('langfuse.observation.metadata.execution_url', execution.url || null),
  attr('langfuse.observation.metadata.controlled_canary', Boolean(source.canary))
];
const span = { traceId, spanId, name: 'prd-genie-workflow-failure', kind: 1, startTimeUnixNano: started.toString(), endTimeUnixNano: ended.toString(), attributes, status: { code: 2, message: errorMessage } };
return [{ json: { trace_id: traceId, run_id: runId, test_id: testId, failed_node: failedNode, error_message: errorMessage, controlled_canary: Boolean(source.canary), otlp_payload: { resourceSpans: [{ resource: { attributes: [attr('service.name', 'prd-genie-n8n'), attr('deployment.environment.name', 'evaluation')] }, scopeSpans: [{ scope: { name: 'prd-genie-failure-observer', version: 'v0.1.0' }, spans: [span] }] }] } } }];

const trace = $('Build Failure Trace').first().json;
const statusCode = $json.statusCode ?? 200;
return [{ json: { schema_version: '1.0.0', trace_id: trace.trace_id, run_id: trace.run_id, test_id: trace.test_id, failed_node: trace.failed_node, controlled_canary: trace.controlled_canary, ingestion_status_code: statusCode, ingestion_accepted: statusCode >= 200 && statusCode < 300, recorded_at: new Date().toISOString() } }];
